class TranslationManager:
    """Gestor de traducciones para la aplicación"""

    def __init__(self):
        self.current_language = 'es'  # Idioma por defecto
        self.config_dir = os.path.expanduser('~/.config/jaime')
        self.config_file = os.path.join(self.config_dir, 'config.json')
        self.load_language()

    def get(self, key, **kwargs):
        """Obtener texto traducido con formato opcional"""
        text = TRANSLATIONS.get(self.current_language, {}).get(key, key)
        if kwargs:
            try:
                return text.format(**kwargs)
            except KeyError:
                return text
        return text

    def set_language(self, lang_code):
        """Cambiar idioma"""
        if lang_code in TRANSLATIONS:
            self.current_language = lang_code
            self.save_language()
            return True
        return False

    def get_language_name(self, lang_code=None):
        """Obtener nombre del idioma"""
        if lang_code is None:
            lang_code = self.current_language

        names = {
            'es': 'Español',
            'en': 'English',
            'pt': 'Português',
            'fr': 'Français',
            'de': 'Deutsch',
            'it': 'Italiano',
            'ru': 'Русский',
            'ar': 'العربية',
            'ro': 'Română',
            'ja': '日本語',
            'zh': '中文',
            'ko': '한국어'
        }
        return names.get(lang_code, 'Unknown')

    def save_language(self):
        """Guardar idioma seleccionado en archivo de configuración"""
        try:
            os.makedirs(self.config_dir, exist_ok=True)
            config = {}

            # Cargar configuración existente si existe
            if os.path.exists(self.config_file):
                with open(self.config_file, 'r') as f:
                    config = json.load(f)

            # Actualizar idioma
            config['language'] = self.current_language

            # Guardar configuración
            with open(self.config_file, 'w') as f:
                json.dump(config, f, indent=2)
        except (IOError, OSError, PermissionError) as e:
            # Silently fail - no es crítico si no se puede guardar la configuración
            pass

    def load_language(self):
        """Cargar idioma desde archivo de configuración"""
        try:
            if os.path.exists(self.config_file):
                with open(self.config_file, 'r') as f:
                    config = json.load(f)
                    lang = config.get('language', 'es')
                    if lang in TRANSLATIONS:
                        self.current_language = lang
        except (IOError, OSError, json.JSONDecodeError):
            # Si hay error, usar idioma por defecto
            self.current_language = 'es'
